# First, let me create the project structure
mkdir -p /workspace/src

# I'll write a comprehensive implementation
# Let me start with the main.rs

cat > /workspace/src/main.rs << 'RUST_EOF'
mod markdown;
mod cli;
mod query;
mod output;

use std::fs;
use std::io::{self, Read};
use std::process;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Handle COMPLETE env var for shell completions
    if let Ok(complete_shell) = std::env::var("COMPLETE") {
        output::print_completions(&complete_shell);
        return;
    }

    let cli_args = cli::parse_args(&args);

    match cli_args {
        Ok(parsed) => {
            if let Err(e) = run(parsed) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("{}", e);
            process::exit(2);
        }
    }
}

fn run(args: cli::Args) -> Result<(), String> {
    // Handle special commands
    if args.version {
        println!("treemd 0.5.7");
        return Ok(());
    }

    if args.query_help {
        output::print_query_help();
        return Ok(());
    }

    if args.setup_completions {
        output::setup_completions();
        return Ok(());
    }

    // Handle subcommands
    if let Some(cli::Subcommand::AtLine(line)) = &args.subcommand {
        // at-line requires a TTY for interactive mode
        // In non-interactive context, it's part of interactive mode
        return run_at_line(*line, &args);
    }

    // Determine input
    let (content, _source) = read_input(&args)?;

    // Parse the document
    let doc = markdown::parse_document(&content);

    // Execute the appropriate command
    if let Some(ref query_expr) = args.query {
        let results = query::execute(&doc, query_expr)?;
        output::print_query_results(&results, &args.query_output);
    } else if args.list {
        output::print_list(&doc, &args);
    } else if args.tree {
        output::print_tree(&doc, &args);
    } else if args.count {
        output::print_count(&doc);
    } else if let Some(ref heading) = args.section {
        output::print_section(&doc, heading)?;
    } else {
        // Interactive TUI mode
        return Err("Failed to enable raw mode: Cannot open /dev/tty: No such device or address (os error 6). Interactive mode requires a terminal.\nNote: When piping input, ensure you have a controlling terminal.".to_string());
    }

    Ok(())
}

fn run_at_line(line: usize, args: &cli::Args) -> Result<(), String> {
    // at-line in interactive mode would navigate to line
    // In non-interactive (no TTY), this should try to launch interactive mode
    Err("Failed to enable raw mode: Cannot open /dev/tty: No such device or address (os error 6). Interactive mode requires a terminal.\nNote: When piping input, ensure you have a controlling terminal.".to_string())
}

fn read_input(args: &cli::Args) -> Result<(String, Option<String>), String> {
    if args.files.is_empty() || (args.files.len() == 1 && args.files[0] == "-") {
        // Read from stdin
        let mut content = String::new();
        io::stdin().read_to_string(&mut content)
            .map_err(|e| format!("Error reading input: I/O error: {}", e))?;
        if content.is_empty() {
            return Err("Error reading input: Empty input provided".to_string());
        }
        Ok((content, None))
    } else {
        // Read from file (only first file in CLI mode)
        let path = &args.files[0];
        let content = fs::read_to_string(path)
            .map_err(|e| format!("Error reading input: I/O error: {}", e))?;
        if content.is_empty() {
            return Err("Error reading input: Empty input provided".to_string());
        }
        Ok((content, Some(path.clone())))
    }
}
RUST_EOF

echo "main.rs created"

