cat > /workspace/src/cli.rs << 'RUST_EOF'
#[derive(Debug)]
pub enum Subcommand {
    AtLine(usize),
}

#[derive(Debug)]
pub struct Args {
    pub files: Vec<String>,
    pub list: bool,
    pub tree: bool,
    pub filter: Option<String>,
    pub level: Option<u8>,
    pub output: OutputFormat,
    pub section: Option<String>,
    pub count: bool,
    pub setup_completions: bool,
    pub theme: Option<String>,
    pub color_mode: Option<String>,
    pub no_images: bool,
    pub images: bool,
    pub query: Option<String>,
    pub query_output: QueryOutputFormat,
    pub query_help: bool,
    pub version: bool,
    pub help: bool,
    pub subcommand: Option<Subcommand>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum OutputFormat {
    Plain,
    Json,
    Tree,
}

#[derive(Debug, Clone, PartialEq)]
pub enum QueryOutputFormat {
    Plain,
    Json,
    JsonPretty,
    Jsonl,
    Md,
    Tree,
}

pub fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut parsed = Args {
        files: Vec::new(),
        list: false,
        tree: false,
        filter: None,
        level: None,
        output: OutputFormat::Plain,
        section: None,
        count: false,
        setup_completions: false,
        theme: None,
        color_mode: None,
        no_images: false,
        images: false,
        query: None,
        query_output: QueryOutputFormat::Plain,
        query_help: false,
        version: false,
        help: false,
        subcommand: None,
    };

    let mut i = 1; // skip program name
    let mut subcommand_mode = false;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" => {
                print_short_help();
                std::process::exit(0);
            }
            "--help" => {
                print_long_help();
                std::process::exit(0);
            }
            "-V" | "--version" => {
                parsed.version = true;
                return Ok(parsed);
            }
            "-l" | "--list" => parsed.list = true,
            "--tree" => parsed.tree = true,
            "--count" => parsed.count = true,
            "--setup-completions" => parsed.setup_completions = true,
            "--no-images" => parsed.no_images = true,
            "--images" => parsed.images = true,
            "--query-help" => parsed.query_help = true,
            "--filter" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --filter requires a value".to_string());
                }
                parsed.filter = Some(args[i].clone());
            }
            s if s.starts_with("--filter=") => {
                parsed.filter = Some(s[9..].to_string());
            }
            "-L" | "--level" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --level requires a value".to_string());
                }
                parsed.level = Some(args[i].parse::<u8>().map_err(|_| "error: invalid level value".to_string())?);
            }
            s if s.starts_with("--level=") => {
                parsed.level = Some(s[8..].parse::<u8>().map_err(|_| "error: invalid level value".to_string())?);
            }
            "-o" | "--output" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --output requires a value".to_string());
                }
                parsed.output = parse_output_format(&args[i])?;
            }
            s if s.starts_with("--output=") => {
                parsed.output = parse_output_format(&s[9..])?;
            }
            "-s" | "--section" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --section requires a value".to_string());
                }
                parsed.section = Some(args[i].clone());
            }
            s if s.starts_with("--section=") => {
                parsed.section = Some(s[10..].to_string());
            }
            "--theme" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --theme requires a value".to_string());
                }
                parsed.theme = Some(args[i].clone());
            }
            "--color-mode" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --color-mode requires a value".to_string());
                }
                parsed.color_mode = Some(args[i].clone());
            }
            "-q" | "--query" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --query requires a value".to_string());
                }
                parsed.query = Some(args[i].clone());
            }
            s if s.starts_with("--query=") => {
                parsed.query = Some(s[8..].to_string());
            }
            "--query-output" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --query-output requires a value".to_string());
                }
                parsed.query_output = parse_query_output_format(&args[i])?;
            }
            "at-line" => {
                // Subcommand
                i += 1;
                if i >= args.len() {
                    return Err("error: the following required arguments were not provided:\n  <LINE>\n\nUsage: executable at-line <LINE>\n\nFor more information, try '--help'.".to_string());
                }
                // Check if the next arg is a file (which is an error)
                if args[i] == "-" || (args[i].ends_with(".md") || args[i].ends_with(".markdown")) {
                    return Err(format!("error: unexpected argument '{}' found\n\nUsage: executable at-line <LINE>\n\nFor more information, try '--help'.", args[i]));
                }
                // Check for subcommand-specific flags
                match args[i].as_str() {
                    "-h" => {
                        print_at_line_help();
                        std::process::exit(0);
                    }
                    "--help" => {
                        print_at_line_long_help();
                        std::process::exit(0);
                    }
                    s => {
                        let line = s.parse::<usize>().map_err(|_| 
                            format!("error: invalid value '{}' for '<LINE>': invalid digit found in string\n\nFor more information, try '--help'.", s)
                        )?;
                        parsed.subcommand = Some(Subcommand::AtLine(line));
                        // Check for unexpected args
                        if i + 1 < args.len() {
                            return Err(format!("error: unexpected argument '{}' found\n\nUsage: executable at-line <LINE>\n\nFor more information, try '--help'.", args[i+1]));
                        }
                    }
                }
            }
            "help" => {
                // help subcommand
                print_long_help();
                std::process::exit(0);
            }
            s if s.starts_with('-') => {
                // Check for combined short flags like -L2
                if s.starts_with("-L") && s.len() > 2 {
                    let level_str = &s[2..];
                    parsed.level = Some(level_str.parse::<u8>().map_err(|_| "error: invalid level value".to_string())?);
                } else {
                    return Err(format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [FILE]... [COMMAND]\n\nFor more information, try '--help'.", s));
                }
            }
            _ => {
                // It's a file or potential subcommand
                parsed.files.push(arg.clone());
            }
        }
        i += 1;
    }

    Ok(parsed)
}

fn parse_output_format(s: &str) -> Result<OutputFormat, String> {
    match s {
        "plain" => Ok(OutputFormat::Plain),
        "json" => Ok(OutputFormat::Json),
        "tree" => Ok(OutputFormat::Tree),
        _ => Err(format!("error: invalid value '{}' for '--output': possible values: plain, json, tree", s)),
    }
}

fn parse_query_output_format(s: &str) -> Result<QueryOutputFormat, String> {
    match s {
        "plain" => Ok(QueryOutputFormat::Plain),
        "json" => Ok(QueryOutputFormat::Json),
        "json-pretty" => Ok(QueryOutputFormat::JsonPretty),
        "jsonp" => Err("Error: Unknown output format: jsonp".to_string()),
        "jsonl" => Ok(QueryOutputFormat::Jsonl),
        "md" => Ok(QueryOutputFormat::Md),
        "tree" => Ok(QueryOutputFormat::Tree),
        _ => Err(format!("Error: Unknown output format: {}", s)),
    }
}

fn print_short_help() {
    println!("A markdown navigator with tree-based structural navigation

Usage: executable [OPTIONS] [FILE]... [COMMAND]

Commands:
  at-line  Show heading at specific line number
  help     Print this message or the help of the given subcommand(s)

Arguments:
  [FILE]...  Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin

Options:
  -l, --list                   List all headings in the document (non-interactive)
      --tree                   Show heading tree structure with box-drawing characters (non-interactive)
      --filter <PATTERN>       Filter headings by text pattern (case-insensitive)
  -L, --level <LEVEL>          Show only headings at specific level (1-6)
  -o, --output <OUTPUT>        Output format for --list and --tree modes [default: plain] [possible values: plain, json, tree]
  -s, --section <HEADING>      Extract specific section by heading name
      --count                  Count headings by level (shows statistics)
      --setup-completions      Set up shell completions interactively
      --theme <THEME>          Set theme for TUI mode
      --color-mode <MODE>      Force color mode (auto, rgb, 256)
      --no-images              Disable image rendering in TUI mode
      --images                 Enable image rendering in TUI mode (override config)
