impl Element {
    pub fn type_name(&self) -> &str {
        match self {
            Element::Heading { .. } => "heading",
            Element::Code { .. } => "code",
            Element::Link { .. } => "link",
            Element::Image { .. } => "image",
            Element::Table { .. } => "table",
            Element::List { .. } => "list",
            Element::Blockquote { .. } => "blockquote",
        }
    }

    pub fn display_text(&self) -> String {
        match self {
            Element::Heading { level, text, .. } => {
                format!("{} {}", "#".repeat(*level as usize), text)
            }
            Element::Code { language, content, .. } => {
                format!("```{}\n{}\n```", language, content)
            }
            Element::Link { text, url, .. } => {
                format!("[{}]({})", text, url)
            }
            Element::Image { alt, src, .. } => {
                format!("![{}]({})", alt, src)
            }
            Element::Table { headers, rows } => {
                let header_row = format!("| {} |", headers.join(" | "));
                let sep_row = format!("| {} |", headers.iter().map(|_| "---").collect::<Vec<_>>().join(" | "));
                let data_rows: Vec<String> = rows.iter().map(|r| format!("| {} |", r.join(" | "))).collect();
                let mut result = vec![header_row, sep_row];
                result.extend(data_rows);
                result.join("\n")
            }
            Element::List { ordered, items } => {
                items.iter().enumerate().map(|(i, item)| {
