pub fn slugify(text: &str) -> String {
    let mut result = String::new();
    let mut prev_hyphen = false;

    for ch in text.chars() {
        if ch.is_alphanumeric() {
            result.push(ch.to_ascii_lowercase());
            prev_hyphen = false;
        } else if ch == ' ' || ch == '-' || ch == '_' {
            if !prev_hyphen && !result.is_empty() {
                result.push('-');
                prev_hyphen = true;
            }
        } else {
            // Skip other punctuation but don't add hyphen
            // Actually non-alpha non-space chars just get removed
            // But if we had "C++" -> "c--" -> "c-" after dedup
            // Let me check: any non-alphanumeric non-space becomes nothing
            // but consecutive hyphens collapse
            // Actually from tests: "C++ Programming" -> "c-programming"
            // "++" -> collapsed to single "-"? No, "C++" -> "c", then "+" -> ""
            // "C++ Programming" = C + ++ + " " + P...
            // = "c" + "" + "" + "-" + "programming" = "c-programming"
            // So non-alphanumeric non-space chars are just removed
            // but if they create consecutive hyphens those get collapsed
        }
    }

    // Remove trailing hyphen
    while result.ends_with('-') {
        result.pop();
    }

    result
}

pub fn strip_inline_markup(text: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        match chars[i] {
            '`' => {
                // Skip inline code content
                i += 1;
                while i < chars.len() && chars[i] != '`' {
                    i += 1;
                }
                // Skip closing backtick
                if i < chars.len() { i += 1; }
            }
            '*' | '_' => {
                // Check for bold (**) or italic (*)
                let marker = chars[i];
                if i + 1 < chars.len() && chars[i + 1] == marker {
                    // Bold - skip the marker
                    i += 2;
                } else {
                    // Italic - skip the marker
                    i += 1;
                }
            }
            '!' if i + 1 < chars.len() && chars[i + 1] == '[' => {
                // Image - skip alt and src
                i += 2;
                // Skip alt text
                while i < chars.len() && chars[i] != ']' { i += 1; }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    while i < chars.len() && chars[i] != ')' { i += 1; }
                    if i < chars.len() { i += 1; }
                }
            }
            '[' => {
                // Link - keep the text, skip the URL
                i += 1;
                let start = result.len();
                while i < chars.len() && chars[i] != ']' {
                    result.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    while i < chars.len() && chars[i] != ')' { i += 1; }
                    if i < chars.len() { i += 1; }
                }
            }
            c => {
                result.push(c);
                i += 1;
            }
        }
    }

    result
}

fn extract_heading_text(text: &str) -> String {
    // For headings, inline code is replaced with empty string
    // bold/italic markers are removed (text kept)
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
