fn find_direct_content_end(
    sections_flat: &[(usize, u8, String, usize, usize)],
    idx: usize,
    content_start: usize,
    total_lines: usize,
) -> usize {
    let (_, level, _, _, _) = &sections_flat[idx];

    // Find the next heading at same or higher level (lower number)
    for j in (idx + 1)..sections_flat.len() {
        if sections_flat[j].1 <= *level {
            return sections_flat[j].0;
        }
    }

    total_lines
}

fn build_tree(sections: Vec<Section>) -> Vec<Section> {
    if sections.is_empty() {
        return sections;
    }

    let mut result: Vec<Section> = Vec::new();
    let mut stack: Vec<Section> = Vec::new();

    for section in sections {
        // Pop sections from stack that are >= current level
        while !stack.is_empty() && stack.last().unwrap().level >= section.level {
            let child = stack.pop().unwrap();
            if let Some(parent) = stack.last_mut() {
                parent.children.push(child);
            } else {
                result.push(child);
            }
        }
        stack.push(section);
    }

    // Drain remaining stack
    while stack.len() > 1 {
        let child = stack.pop().unwrap();
        stack.last_mut().unwrap().children.push(child);
    }
    if let Some(top) = stack.pop() {
        result.push(top);
    }

    result
}

fn count_all_headings(sections: &[Section]) -> usize {
    sections.iter().map(|s| 1 + count_all_headings(&s.children)).sum()
}

fn calc_max_depth(sections: &[Section], current_depth: usize) -> usize {
    if sections.is_empty() {
        return current_depth;
    }
    sections.iter().map(|s| {
        let children_depth = calc_max_depth(&s.children, current_depth + 1);
        children_depth.max(current_depth + 1)
    }).max().unwrap_or(current_depth)
}

fn parse_atx_heading(line: &str) -> Option<(u8, String)> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('#') {
        return None;
    }

    let mut level = 0u8;
    let chars: Vec<char> = trimmed.chars().collect();

    while level < chars.len() as u8 && chars[level as usize] == '#' {
        level += 1;
    }

    if level > 6 {
        return None;
    }

    if level as usize >= chars.len() {
        // Just hashes, no content - return empty heading
        return Some((level, String::new()));
    }

    // Must have a space after the hashes
    if chars[level as usize] != ' ' {
        return None;
    }

    let text: String = chars[(level as usize + 1)..].iter().collect();
    // Remove trailing hashes if present
    let text = text.trim_end_matches('#').trim_end().to_string();

    Some((level, text))
}

pub fn parse_blocks(content: &str) -> Vec<Block> {
    let mut blocks = Vec::new();
    let lines: Vec<&str> = content.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];

        // Skip blank lines between blocks
        if line.trim().is_empty() {
            i += 1;
            continue;
        }

        // Code block
        if line.trim_start().starts_with("```") {
            let fence_line = line.trim_start();
            let lang = fence_line[3..].trim().to_string();
            i += 1;
            let mut code_lines = Vec::new();
            while i < lines.len() && !lines[i].trim_start().starts_with("```") {
                code_lines.push(lines[i]);
                i += 1;
            }
            if i < lines.len() { i += 1; } // skip closing ```
            blocks.push(Block::Code {
                language: lang,
                content: code_lines.join("\n"),
                start_line: 1,
                end_line: 1,
            });
            continue;
        }

        // Table
        if line.contains('|') && i + 1 < lines.len() && lines[i+1].contains('|') && lines[i+1].contains('-') {
            // Parse table
            let headers = parse_table_row(line);
            i += 1; // skip separator
            i += 1;
            let mut rows = Vec::new();
            while i < lines.len() && lines[i].contains('|') && !lines[i].trim().is_empty() {
                rows.push(parse_table_row(lines[i]));
                i += 1;
            }
            blocks.push(Block::Table { headers, rows });
            continue;
        }

        // List
        if is_list_item(line) {
            let mut items = Vec::new();
            let ordered = line.trim_start().chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
            while i < lines.len() && (is_list_item(lines[i]) || is_list_continuation(lines[i])) {
                if is_list_item(lines[i]) {
                    let (content, checked) = parse_list_item(lines[i]);
                    let inline = parse_inline(&content);
                    items.push(ListItem { content, checked, inline });
                }
                i += 1;
            }
            blocks.push(Block::List { ordered, items });
            continue;
        }

        // Blockquote
        if line.trim_start().starts_with('>') {
            let mut bq_lines = Vec::new();
            while i < lines.len() && lines[i].trim_start().starts_with('>') {
                let bq_line = lines[i].trim_start().trim_start_matches('>').trim_start();
                bq_lines.push(bq_line.to_string());
                i += 1;
            }
            // Don't add as a block (blockquotes don't appear in query results based on testing)
            // Actually just skip them for now - test showed empty blockquote output
            continue;
        }

        // ATX Heading within content
        if let Some((level, text)) = parse_atx_heading(line) {
            let anchor = slugify(&text);
            let inline = parse_inline(&text);
            blocks.push(Block::Heading {
                level,
                content: text,
                inline,
                anchor,
            });
            i += 1;
            continue;
        }

        // Setext heading check
        if i + 1 < lines.len() {
            let next = lines[i + 1];
            let next_trimmed = next.trim();
            if !next_trimmed.is_empty() && next_trimmed.chars().all(|c| c == '=') {
                let text = line.trim().to_string();
                let anchor = slugify(&text);
                let inline = parse_inline(&text);
                blocks.push(Block::Heading {
                    level: 1,
                    content: text,
                    inline,
                    anchor,
                });
                i += 2;
                continue;
            }
            if !next_trimmed.is_empty() && next_trimmed.chars().all(|c| c == '-') && next_trimmed.len() >= 2 {
                let text = line.trim().to_string();
                let anchor = slugify(&text);
                let inline = parse_inline(&text);
                blocks.push(Block::Heading {
                    level: 2,
                    content: text,
                    inline,
                    anchor,
                });
                i += 2;
                continue;
            }
        }

        // Paragraph - collect until blank line or block start
        let mut para_lines = Vec::new();
        while i < lines.len() && !lines[i].trim().is_empty() 
            && !lines[i].trim_start().starts_with("```")
            && !is_list_item(lines[i])
            && !lines[i].trim_start().starts_with('>')
        {
            // Check if next line is setext marker
            if i + 1 < lines.len() {
                let next = lines[i + 1].trim();
                if !next.is_empty() && (next.chars().all(|c| c == '=') || 
                    (next.chars().all(|c| c == '-') && next.len() >= 2)) {
                    para_lines.push(lines[i]);
                    break;
                }
            }
            para_lines.push(lines[i]);
            i += 1;
        }

        if !para_lines.is_empty() {
            let content = para_lines.join("\n");
            let inline = parse_inline(&content);
            blocks.push(Block::Paragraph { content, inline });
        }
    }

    blocks
}

fn parse_table_row(line: &str) -> Vec<String> {
    let line = line.trim();
    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').map(|cell| cell.trim().to_string()).collect()
}

fn is_list_item(line: &str) -> bool {
    let trimmed = line.trim_start();
    if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") {
        return true;
    }
    // Check ordered list
    let mut chars = trimmed.chars();
    let mut has_digit = false;
    loop {
        match chars.next() {
            Some(c) if c.is_ascii_digit() => has_digit = true,
            Some('.') | Some(')') if has_digit => return chars.next() == Some(' '),
            _ => break,
        }
    }
    false
}

fn is_list_continuation(line: &str) -> bool {
    // A list continuation is indented content
    line.starts_with("  ") || line.starts_with("\t")
}

fn parse_list_item(line: &str) -> (String, Option<bool>) {
    let trimmed = line.trim_start();

    // Check for checkbox
    if trimmed.starts_with("- [ ] ") || trimmed.starts_with("* [ ] ") {
        return (trimmed[6..].to_string(), Some(false));
    }
    if trimmed.starts_with("- [x] ") || trimmed.starts_with("* [x] ") 
        || trimmed.starts_with("- [X] ") || trimmed.starts_with("* [X] ") {
        return (trimmed[6..].to_string(), Some(true));
    }

    // Unordered
    if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") {
        return (trimmed[2..].to_string(), None);
    }

    // Ordered
    if let Some(pos) = trimmed.find(". ") {
        let prefix = &trimmed[..pos];
        if prefix.chars().all(|c| c.is_ascii_digit()) {
            return (trimmed[pos+2..].to_string(), None);
        }
    }

    (trimmed.to_string(), None)
}

pub fn parse_inline(text: &str) -> Vec<InlineItem> {
    let mut items = Vec::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    let mut current_text = String::new();

    while i < chars.len() {
        match chars[i] {
            '!' if i + 1 < chars.len() && chars[i+1] == '[' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 2;
                let mut alt = String::new();
                while i < chars.len() && chars[i] != ']' {
                    alt.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    let mut url = String::new();
                    let mut title: Option<String> = None;
                    while i < chars.len() && chars[i] != ')' {
                        if chars[i] == '"' {
                            i += 1;
                            let mut t = String::new();
                            while i < chars.len() && chars[i] != '"' {
                                t.push(chars[i]);
                                i += 1;
                            }
                            if i < chars.len() { i += 1; }
                            title = Some(t);
                        } else {
                            url.push(chars[i]);
                            i += 1;
                        }
                    }
                    if i < chars.len() { i += 1; } // skip )
                    let url = url.trim().to_string();
                    items.push(InlineItem::Image { alt, src: url, title });
                } else {
                    items.push(InlineItem::Text { value: format!("![{}]", alt) });
                }
            }
            '[' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 1;
                let mut link_text = String::new();
                while i < chars.len() && chars[i] != ']' {
                    link_text.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    let mut url = String::new();
                    let mut title: Option<String> = None;
                    while i < chars.len() && chars[i] != ')' {
                        if chars[i] == '"' {
                            i += 1;
                            let mut t = String::new();
                            while i < chars.len() && chars[i] != '"' {
                                t.push(chars[i]);
                                i += 1;
                            }
                            if i < chars.len() { i += 1; }
                            title = Some(t);
                        } else {
                            url.push(chars[i]);
                            i += 1;
                        }
                    }
                    if i < chars.len() { i += 1; } // skip )
                    let url = url.trim().to_string();
                    items.push(InlineItem::Link { text: link_text, url, title });
                } else {
                    items.push(InlineItem::Text { value: format!("[{}]", link_text) });
                }
            }
            '`' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 1;
                let mut code = String::new();
                while i < chars.len() && chars[i] != '`' {
                    code.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; }
                items.push(InlineItem::Code { value: code });
            }
            '*' | '_' => {
                let marker = chars[i];
                if i + 1 < chars.len() && chars[i+1] == marker {
                    // Bold
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    i += 2;
                    let mut bold = String::new();
                    while i + 1 < chars.len() && !(chars[i] == marker && chars[i+1] == marker) {
                        bold.push(chars[i]);
                        i += 1;
                    }
                    if i + 1 < chars.len() { i += 2; }
                    items.push(InlineItem::Bold { value: bold });
                } else {
                    // Italic
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    i += 1;
                    let mut italic = String::new();
                    while i < chars.len() && chars[i] != marker {
                        italic.push(chars[i]);
                        i += 1;
                    }
                    if i < chars.len() { i += 1; }
                    items.push(InlineItem::Italic { value: italic });
                }
            }
            c => {
                current_text.push(c);
                i += 1;
            }
        }
    }

    if !current_text.is_empty() {
        items.push(InlineItem::Text { value: current_text });
    }

    items
}

// Collect all elements from the document for querying
pub fn collect_all_headings(doc: &Document) -> Vec<Element> {
    let mut headings = Vec::new();
    collect_headings_from_sections(&doc.sections, &mut headings);
    headings
}

fn collect_headings_from_sections(sections: &[Section], out: &mut Vec<Element>) {
    for section in sections {
        // The heading's actual line number
        let heading_line = section.position.line - 1; // position.line = content_start = heading_line + 1
        out.push(Element::Heading {
            level: section.level,
            text: section.title.clone(),
            line: heading_line,
            section: section.clone(),
        });
        collect_headings_from_sections(&section.children, out);
    }
}

pub fn collect_all_code_blocks(doc: &Document) -> Vec<Element> {
    let mut blocks = Vec::new();
    collect_code_from_sections(&doc.sections, &mut blocks);
    blocks
}

fn collect_code_from_sections(sections: &[Section], out: &mut Vec<Element>) {
    for section in sections {
        for block in &section.content.blocks {
            if let Block::Code { language, content, start_line, end_line } = block {
                out.push(Element::Code {
                    language: language.clone(),
                    content: content.clone(),
                    start_line: *start_line,
                    end_line: *end_line,
                });
            }
        }
        collect_code_from_sections(&section.children, out);
    }
}

pub fn collect_all_links(doc: &Document) -> Vec<Element> {
    let mut links = Vec::new();
    collect_links_from_sections(&doc.sections, &mut links);
    links
}

fn collect_links_from_sections(sections: &[Section], out: &mut Vec<Element>) {
    for section in sections {
        for block in &section.content.blocks {
            collect_links_from_block(block, out);
        }
        collect_links_from_sections(&section.children, out);
    }
}

fn collect_links_from_block(block: &Block, out: &mut Vec<Element>) {
    match block {
        Block::Paragraph { inline, .. } => {
            for item in inline {
                if let InlineItem::Link { text, url, .. } = item {
                    let link_type = classify_link(url);
                    out.push(Element::Link {
                        text: text.clone(),
                        url: url.clone(),
                        link_type,
                    });
                }
            }
        }
        Block::List { items, .. } => {
            for item in items {
                for inline_item in &item.inline {
                    if let InlineItem::Link { text, url, .. } = inline_item {
                        let link_type = classify_link(url);
                        out.push(Element::Link {
                            text: text.clone(),
                            url: url.clone(),
                            link_type,
                        });
                    }
                }
            }
        }
        _ => {}
    }
}

fn classify_link(url: &str) -> String {
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("ftp://") {
        "external".to_string()
    } else if url.starts_with('#') {
        "anchor".to_string()
    } else {
        "relative".to_string()
    }
}

