impl Element {
    pub fn type_name(&self) -> &str {
        match self {
            Element::Heading { .. } => "heading",
            Element::Code { .. } => "code",
            Element::Link { .. } => "link",
            Element::Image { .. } => "image",
            Element::Table { .. } => "table",
            Element::List { .. } => "list",
            Element::Blockquote { .. } => "blockquote",
