            let min = elems.into_iter()
                .filter_map(|e| match e {
                    Element::Heading { text, .. } => Some(text),
                    _ => None,
                })
                .min();
            match min {
                Some(s) => Ok(QueryResult::Strings(vec![s])),
                None => Ok(QueryResult::Strings(vec!["".to_string()])),
            }
        }
        _ => Ok(QueryResult::Strings(vec!["".to_string()])),
    }
}

