fn apply_content(input: QueryResult) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let texts: Vec<String> = elems.iter()
                .filter_map(|e| match e {
                    Element::Heading { section, .. } => {
                        // Content is the section's content (not including child headings)
                        Some(section.content.raw.clone())
                    }
                    _ => None,
                })
                .collect();
            Ok(QueryResult::Strings(texts))
        }
        _ => Ok(QueryResult::Strings(vec![])),
    }
