fn apply_md(input: QueryResult) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let texts: Vec<String> = elems.iter()
                .map(|e| match e {
                    Element::Heading { level, text, section, .. } => {
                        let prefix = "#".repeat(*level as usize);
                        let mut result = format!("{} {}\n", prefix, text);
                        if !section.content.raw.is_empty() {
                            result.push('\n');
                            result.push_str(&section.content.raw);
                            result.push('\n');
                        }
                        // Add children
                        for child in &section.children {
                            result.push('\n');
                            result.push_str(&format_section_as_md(child));
                            result.push('\n');
                        }
                        result
                    }
                    _ => e.display_text(),
                })
                .collect();
            Ok(QueryResult::Strings(texts))
        }
        _ => Ok(QueryResult::Strings(vec![])),
    }
}

fn format_section_as_md(section: &Section) -> String {
    let prefix = "#".repeat(section.level as usize);
    let mut result = format!("{} {}\n", prefix, section.title);
    if !section.content.raw.is_empty() {
        result.push('\n');
        result.push_str(&section.content.raw);
        result.push('\n');
    }
    for child in &section.children {
        result.push('\n');
        result.push_str(&format_section_as_md(child));
        result.push('\n');
    }
    result
}

fn apply_split(input: QueryResult, sep: &str) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let mut all_parts = Vec::new();
            for e in &elems {
                let text = match e {
                    Element::Heading { text, .. } => text.clone(),
                    _ => e.display_text(),
                };
                for part in text.split(sep) {
                    all_parts.push(part.to_string());
                }
            }
            Ok(QueryResult::Strings(all_parts))
        }
        QueryResult::Strings(strs) => {
            let mut all_parts = Vec::new();
            for s in strs {
                for part in s.split(sep) {
                    all_parts.push(part.to_string());
                }
            }
            Ok(QueryResult::Strings(all_parts))
        }
        other => Ok(other),
    }
}

