                    Element::Heading { text, .. } => text.clone(),
                    _ => e.display_text(),
                })
                .collect();
            Ok(QueryResult::Strings(vec![texts.join(sep)]))
        }
        QueryResult::Strings(strs) => {
            Ok(QueryResult::Strings(vec![strs.join(sep)]))
        }
        other => Ok(other),
    }
}

fn apply_replace(input: QueryResult, from: &str, to: &str) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let texts: Vec<String> = elems.iter()
                .map(|e| match e {
                    Element::Heading { text, .. } => text.replace(from, to),
                    _ => e.display_text().replace(from, to),
                })
                .collect();
            Ok(QueryResult::Strings(texts))
        }
        QueryResult::Strings(strs) => {
            Ok(QueryResult::Strings(strs.into_iter().map(|s| s.replace(from, to)).collect()))
        }
        other => Ok(other),
    }
}

fn apply_contains_func(input: QueryResult, s: &str) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let bools: Vec<bool> = elems.iter()
                .map(|e| match e {
                    Element::Heading { text, .. } => text.contains(s),
                    _ => e.display_text().contains(s),
                })
                .collect();
            Ok(QueryResult::Bools(bools))
