fn apply_not_func(input: QueryResult, expr: &str, doc: &Document) -> Result<QueryResult, String> {
    // not(contains("Mode")) applied to elements
    // First evaluate the inner expression for each element
    match input {
        QueryResult::Elements(elems) => {
            let filtered: Vec<Element> = elems.into_iter()
                .filter(|e| {
                    // Evaluate expr for this element
                    let single_result = apply_function(
                        QueryResult::Elements(vec![e.clone()]), 
                        expr, 
                        doc
                    );
                    match single_result {
                        Ok(QueryResult::Bools(bools)) => !bools.into_iter().all(|b| b),
                        Ok(QueryResult::Elements(elems)) => elems.is_empty(),
                        _ => true,
                    }
                })
                .collect();
            Ok(QueryResult::Elements(filtered))
        }
        other => Ok(other),
    }
}

fn apply_any_func(input: QueryResult, condition: &str) -> Result<QueryResult, String> {
    match input {
        QueryResult::Elements(elems) => {
            let any = elems.iter().any(|e| {
                let single = apply_function(
                    QueryResult::Elements(vec![e.clone()]),
                    condition,
                    &dummy_doc(),
                );
                match single {
                    Ok(QueryResult::Bools(bools)) => bools.into_iter().any(|b| b),
                    _ => false,
                }
            });
            Ok(QueryResult::Bools(vec![any]))
        }
        other => Ok(QueryResult::Bools(vec![true])),
    }
}

fn apply_all_func(input: QueryResult, condition: &str) -> Result<QueryResult, String> {
    match input {
