fn apply_levels(doc: &Document) -> Result<QueryResult, String> {
    let headings = markdown::collect_all_headings(doc);
    let mut counts = [0usize; 7];
    for h in &headings {
        if let Element::Heading { level, .. } = h {
            if *level <= 6 {
                counts[*level as usize] += 1;
            }
        }
    }

    let mut result = String::new();
    for level in 1..=6 {
        if counts[level] > 0 {
            if !result.is_empty() { result.push('\n'); }
            result.push_str(&format!("h{}: {}", level, counts[level]));
        }
    }

    Ok(QueryResult::Strings(vec![result]))
}

fn apply_langs(doc: &Document) -> Result<QueryResult, String> {
    let code_blocks = markdown::collect_all_code_blocks(doc);
    let mut counts: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for block in &code_blocks {
        if let Element::Code { language, .. } = block {
            if !language.is_empty() {
                *counts.entry(language.clone()).or_insert(0) += 1;
            }
        }
    }

    let mut result = String::new();
    for (lang, count) in &counts {
        if !result.is_empty() { result.push('\n'); }
        result.push_str(&format!("{}: {}", lang, count));
    }

    Ok(QueryResult::Strings(vec![result]))
}

fn apply_types(doc: &Document) -> Result<QueryResult, String> {
    let links = markdown::collect_all_links(doc);
    let mut counts: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for link in &links {
        if let Element::Link { link_type, .. } = link {
            *counts.entry(link_type.clone()).or_insert(0) += 1;
        }
    }

    let mut result = String::new();
    for (t, count) in &counts {
        if !result.is_empty() { result.push('\n'); }
        result.push_str(&format!("{}: {}", t, count));
    }

    Ok(QueryResult::Strings(vec![result]))
}
