pub fn setup_completions() {
    // Try to detect shell
    let shell = std::env::var("SHELL").ok();
    let detected = shell.as_deref().map(|s| {
        if s.contains("bash") { "bash" }
        else if s.contains("zsh") { "zsh" }
        else if s.contains("fish") { "fish" }
        else { "" }
    }).unwrap_or("");

    if detected.is_empty() {
        eprintln!("Error setting up completions: Could not detect shell");
    }

    println!("Shell Completion Setup Instructions\n");
    println!("Add the appropriate line to your shell config:\n");
    println!("Bash (~/.bashrc):");
    println!("  source <(COMPLETE=bash treemd)\n");
    println!("Zsh (~/.zshrc):");
    println!("  source <(COMPLETE=zsh treemd)\n");
    println!("Fish (~/.config/fish/config.fish):");
    println!("  COMPLETE=fish treemd | source\n");
    println!("After adding the line, restart your shell or source the config file.");
}

