fn print_tree_sections(sections: &[Section], prefix: &str, is_last_group: bool) {
    let count = sections.len();
    for (i, section) in sections.iter().enumerate() {
        let is_last = i == count - 1;
        let connector = if is_last { "└──" } else { "├──" };
        let child_prefix = if is_last { "   " } else { "│  " };

        let heading = format!("{}{}{} {}", prefix, connector, 
            "#".repeat(section.level as usize), section.title);
        println!("{}", heading);

        if !section.children.is_empty() {
            let new_prefix = format!("{}{}", prefix, child_prefix);
            print_tree_sections(&section.children, &new_prefix, false);
        }
    }
