fn format_content_json(content: &crate::markdown::SectionContent) -> String {
    let blocks_json: Vec<String> = content.blocks.iter().map(format_block_json).collect();
    format!(
        "{{\"raw\":{},\"blocks\":[{}]}}",
        json_string(&content.raw),
        blocks_json.join(","),
    )
}

fn format_block_json(block: &crate::markdown::Block) -> String {
    use crate::markdown::Block;
    match block {
        Block::Paragraph { content, inline } => {
            let inline_json = format_inline_json(inline);
            format!(
                "{{\"type\":\"paragraph\",\"content\":{},\"inline\":{}}}",
                json_string(content),
                inline_json,
            )
        }
        Block::Heading { level, content, inline, anchor } => {
            let inline_json = format_inline_json(inline);
            format!(
                "{{\"type\":\"heading\",\"level\":{},\"content\":{},\"inline\":{},\"anchor\":{}}}",
                level,
                json_string(content),
                inline_json,
                json_string(anchor),
            )
        }
        Block::Code { language, content, start_line, end_line } => {
            format!(
                "{{\"type\":\"code\",\"language\":{},\"content\":{},\"start_line\":{},\"end_line\":{}}}",
                json_string(language),
                json_string(content),
                start_line,
                end_line,
            )
        }
        Block::List { ordered, items } => {
            let items_json: Vec<String> = items.iter().map(|item| {
                let inline_json = format_inline_json(&item.inline);
                let checked = match item.checked {
                    None => "null".to_string(),
                    Some(b) => b.to_string(),
                };
                format!(
                    "{{\"checked\":{},\"content\":{},\"inline\":{}}}",
                    checked,
                    json_string(&item.content),
                    inline_json,
                )
            }).collect();
            format!(
                "{{\"type\":\"list\",\"ordered\":{},\"items\":[{}]}}",
                ordered,
                items_json.join(","),
            )
        }
        Block::Table { headers, rows } => {
            let headers_json: Vec<String> = headers.iter().map(|h| json_string(h)).collect();
            let rows_json: Vec<String> = rows.iter().map(|row| {
                let cells: Vec<String> = row.iter().map(|c| json_string(c)).collect();
                format!("[{}]", cells.join(","))
            }).collect();
            format!(
                "{{\"type\":\"table\",\"headers\":[{}],\"rows\":[{}]}}",
                headers_json.join(","),
                rows_json.join(","),
            )
        }
        Block::Blockquote { content } => {
            format!(
                "{{\"type\":\"blockquote\",\"content\":{}}}",
                json_string(content),
            )
        }
    }
}

fn format_inline_json(inline: &[crate::markdown::InlineItem]) -> String {
    use crate::markdown::InlineItem;
    let items: Vec<String> = inline.iter().map(|item| {
        match item {
            InlineItem::Text { value } => format!("{{\"type\":\"text\",\"value\":{}}}", json_string(value)),
