// JSON utility functions
pub fn json_string(s: &str) -> String {
    let mut result = String::with_capacity(s.len() + 2);
    result.push('"');
    for ch in s.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn pretty_print_json(json: &str) -> String {
    let mut result = String::new();
    let mut indent = 0;
    let mut in_string = false;
    let mut prev_char = ' ';
    let chars: Vec<char> = json.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let ch = chars[i];

        if in_string {
            result.push(ch);
            if ch == '"' && prev_char != '\\' {
                in_string = false;
            }
            prev_char = ch;
            i += 1;
            continue;
        }

        match ch {
            '"' => {
                in_string = true;
                result.push(ch);
            }
            '{' | '[' => {
                result.push(ch);
                // Check if empty
                if i + 1 < chars.len() && (chars[i+1] == '}' || chars[i+1] == ']') {
                    // Don't add newline for empty objects/arrays
                } else {
                    indent += 2;
                    result.push('\n');
                    result.push_str(&" ".repeat(indent));
                }
            }
            '}' | ']' => {
                indent -= 2;
                if prev_char != '{' && prev_char != '[' {
                    result.push('\n');
                    result.push_str(&" ".repeat(indent));
                }
                result.push(ch);
            }
            ',' => {
                result.push(ch);
                result.push('\n');
                result.push_str(&" ".repeat(indent));
            }
            ':' => {
                result.push(':');
                result.push(' ');
            }
            ' ' | '\n' | '\r' | '\t' => {
                // Skip whitespace in non-string context
            }
            _ => {
                result.push(ch);
            }
        }

        if ch != ' ' && ch != '\n' && ch != '\r' && ch != '\t' {
            prev_char = ch;
        }
        i += 1;
    }

    result
}
RUST_EOF

