fn get_all_headings_flat(sections: &[Section]) -> Vec<(u8, String)> {
    let mut result = Vec::new();
    for section in sections {
        result.push((section.level, section.title.clone()));
        result.extend(get_all_headings_flat(&section.children));
    }
    result
}

