fn format_document_json(doc: &Document) -> String {
    let metadata = format!(
        "{{\"source\":null,\"headingCount\":{},\"maxDepth\":{},\"wordCount\":{}}}",
        doc.metadata.heading_count,
        doc.metadata.max_depth,
        doc.metadata.word_count,
    );

    let sections_json = format_sections_json(&doc.sections);

    format!("{{\"document\":{{\"metadata\":{},\"sections\":{}}}}}", metadata, sections_json)
}

fn format_sections_json(sections: &[Section]) -> String {
    let items: Vec<String> = sections.iter().map(format_section_json).collect();
    format!("[{}]", items.join(","))
}

fn format_section_json(section: &Section) -> String {
    let children_json = format_sections_json(&section.children);
    let content_json = format_content_json(&section.content);

    format!(
        "{{\"id\":{},\"level\":{},\"title\":{},\"slug\":{},\"position\":{{\"line\":{},\"offset\":{}}},\"content\":{},\"children\":{}}}",
        json_string(&section.id),
        section.level,
        json_string(&section.title),
        json_string(&section.slug),
        section.position.line,
        section.position.offset,
        content_json,
        children_json,
    )
}

fn format_content_json(content: &crate::markdown::SectionContent) -> String {
    let blocks_json: Vec<String> = content.blocks.iter().map(format_block_json).collect();
    format!(
        "{{\"raw\":{},\"blocks\":[{}]}}",
        json_string(&content.raw),
        blocks_json.join(","),
    )
}

fn format_block_json(block: &crate::markdown::Block) -> String {
    use crate::markdown::Block;
    match block {
        Block::Paragraph { content, inline } => {
            let inline_json = format_inline_json(inline);
            format!(
                "{{\"type\":\"paragraph\",\"content\":{},\"inline\":{}}}",
                json_string(content),
                inline_json,
            )
        }
        Block::Heading { level, content, inline, anchor } => {
            let inline_json = format_inline_json(inline);
            format!(
                "{{\"type\":\"heading\",\"level\":{},\"content\":{},\"inline\":{},\"anchor\":{}}}",
                level,
                json_string(content),
                inline_json,
                json_string(anchor),
            )
        }
        Block::Code { language, content, start_line, end_line } => {
            format!(
                "{{\"type\":\"code\",\"language\":{},\"content\":{},\"start_line\":{},\"end_line\":{}}}",
                json_string(language),
                json_string(content),
                start_line,
                end_line,
            )
        }
        Block::List { ordered, items } => {
            let items_json: Vec<String> = items.iter().map(|item| {
                let inline_json = format_inline_json(&item.inline);
                let checked = match item.checked {
                    None => "null".to_string(),
                    Some(b) => b.to_string(),
                };
                format!(
                    "{{\"checked\":{},\"content\":{},\"inline\":{}}}",
                    checked,
                    json_string(&item.content),
                    inline_json,
                )
            }).collect();
            format!(
                "{{\"type\":\"list\",\"ordered\":{},\"items\":[{}]}}",
                ordered,
                items_json.join(","),
            )
        }
        Block::Table { headers, rows } => {
            let headers_json: Vec<String> = headers.iter().map(|h| json_string(h)).collect();
            let rows_json: Vec<String> = rows.iter().map(|row| {
                let cells: Vec<String> = row.iter().map(|c| json_string(c)).collect();
                format!("[{}]", cells.join(","))
            }).collect();
            format!(
                "{{\"type\":\"table\",\"headers\":[{}],\"rows\":[{}]}}",
                headers_json.join(","),
                rows_json.join(","),
            )
        }
        Block::Blockquote { content } => {
            format!(
                "{{\"type\":\"blockquote\",\"content\":{}}}",
                json_string(content),
            )
        }
    }
}

fn format_inline_json(inline: &[crate::markdown::InlineItem]) -> String {
    use crate::markdown::InlineItem;
    let items: Vec<String> = inline.iter().map(|item| {
        match item {
            InlineItem::Text { value } => format!("{{\"type\":\"text\",\"value\":{}}}", json_string(value)),
            InlineItem::Code { value } => format!("{{\"type\":\"code\",\"value\":{}}}", json_string(value)),
            InlineItem::Bold { value } => format!("{{\"type\":\"bold\",\"value\":{}}}", json_string(value)),
            InlineItem::Italic { value } => format!("{{\"type\":\"italic\",\"value\":{}}}", json_string(value)),
            InlineItem::Link { text, url, title } => {
                let title_json = match title {
                    None => "null".to_string(),
                    Some(t) => json_string(t),
                };
                format!(
                    "{{\"type\":\"link\",\"text\":{},\"url\":{},\"title\":{}}}",
                    json_string(text), json_string(url), title_json,
                )
            }
            InlineItem::Image { alt, src, title } => {
                let title_json = match title {
                    None => "null".to_string(),
                    Some(t) => json_string(t),
                };
                format!(
                    "{{\"type\":\"image\",\"alt\":{},\"src\":{},\"title\":{}}}",
                    json_string(alt), json_string(src), title_json,
