pub fn print_count(doc: &Document) {
    let headings = get_all_headings_flat(&doc.sections);
    let mut counts = [0usize; 7];
    for (level, _) in &headings {
        if *level <= 6 {
            counts[*level as usize] += 1;
        }
    }

    println!("Heading counts:");
    for level in 1..=6 {
        if counts[level] > 0 {
            let prefix = "#".repeat(level);
            println!("  {}: {}", prefix, counts[level]);
        }
    }

    let total: usize = counts.iter().sum();
    println!();
    println!("Total: {}", total);
}

pub fn print_section(doc: &Document, heading: &str) -> Result<(), String> {
    // Find the section with this heading (case-insensitive)
    let found = find_section_by_heading(&doc.sections, heading);

    match found {
        Some(section) => {
            // Print the heading
            let prefix = "#".repeat(section.level as usize);
            println!("{} {}", prefix, section.title);

            // Print content
            if !section.content.raw.is_empty() {
                println!();
                println!("{}", section.content.raw);
            }

            // Print children
            for child in &section.children {
                println!();
                print_section_recursive(child);
            }

            Ok(())
        }
        None => {
            eprintln!("Section '{}' not found", heading);
            Err(format!("Section '{}' not found", heading))
        }
    }
}

fn print_section_recursive(section: &Section) {
    let prefix = "#".repeat(section.level as usize);
    println!("{} {}", prefix, section.title);

    if !section.content.raw.is_empty() {
        println!();
        println!("{}", section.content.raw);
    }

    for child in &section.children {
        println!();
        print_section_recursive(child);
    }
}

fn find_section_by_heading<'a>(sections: &'a [Section], heading: &str) -> Option<&'a Section> {
    for section in sections {
        if section.title.to_lowercase() == heading.to_lowercase() {
            return Some(section);
        }
        if let Some(found) = find_section_by_heading(&section.children, heading) {
            return Some(found);
        }
    }
    None
}

