fn element_to_json(elem: &Element) -> String {
    match elem {
        Element::Heading { level, text, line, .. } => {
            format!(
                "{{\"type\":\"heading\",\"level\":{},\"text\":{},\"line\":{}}}",
                level, json_string(text), line
            )
        }
        Element::Code { language, content, start_line, end_line } => {
            format!(
                "{{\"type\":\"code\",\"language\":{},\"content\":{},\"start_line\":{},\"end_line\":{}}}",
                json_string(language), json_string(content), start_line, end_line
            )
        }
        Element::Link { text, url, link_type } => {
            format!(
                "{{\"type\":\"link\",\"text\":{},\"url\":{},\"link_type\":{}}}",
                json_string(text), json_string(url), json_string(link_type)
            )
        }
        Element::Image { alt, src, title } => {
            let title_json = match title {
                None => "null".to_string(),
                Some(t) => json_string(t),
            };
            format!(
                "{{\"type\":\"image\",\"alt\":{},\"src\":{},\"title\":{}}}",
                json_string(alt), json_string(src), title_json
            )
        }
        Element::Table { headers, rows } => {
            let h: Vec<String> = headers.iter().map(|h| json_string(h)).collect();
            let r: Vec<String> = rows.iter().map(|row| {
                let cells: Vec<String> = row.iter().map(|c| json_string(c)).collect();
                format!("[{}]", cells.join(","))
            }).collect();
            format!(
                "{{\"type\":\"table\",\"headers\":[{}],\"rows\":[{}]}}",
                h.join(","), r.join(",")
            )
        }
        Element::List { ordered, items } => {
            let items_json: Vec<String> = items.iter().map(|item| {
                let checked = match item.checked {
                    None => "null".to_string(),
                    Some(b) => b.to_string(),
                };
                format!(
                    "{{\"content\":{},\"checked\":{}}}",
                    json_string(&item.content), checked
                )
            }).collect();
            format!(
                "{{\"type\":\"list\",\"ordered\":{},\"items\":[{}]}}",
                ordered, items_json.join(",")
            )
        }
        Element::Blockquote { content } => {
            format!("{{\"type\":\"blockquote\",\"content\":{}}}", json_string(content))
        }
    }
}

fn print_query_json(results: &QueryResult) {
    match results {
        QueryResult::Elements(elems) => {
            if elems.len() == 1 {
                println!("{}", element_to_json(&elems[0]));
            } else {
                let items: Vec<String> = elems.iter().map(element_to_json).collect();
                println!("[{}]", items.join(","));
            }
        }
        QueryResult::Strings(strs) => {
            if strs.len() == 1 {
                println!("{}", json_string(&strs[0]));
            } else {
                let items: Vec<String> = strs.iter().map(|s| json_string(s)).collect();
                println!("[{}]", items.join(","));
            }
        }
        QueryResult::Number(n) => println!("{}", n),
        QueryResult::Bool(b) => println!("{}", b),
        QueryResult::Bools(bools) => {
            let items: Vec<String> = bools.iter().map(|b| b.to_string()).collect();
            println!("[{}]", items.join(","));
        }
        _ => {}
    }
}

fn print_query_json_pretty(results: &QueryResult) {
    match results {
        QueryResult::Elements(elems) => {
            let json_str = if elems.len() == 1 {
                element_to_json(&elems[0])
            } else {
                let items: Vec<String> = elems.iter().map(element_to_json).collect();
                format!("[{}]", items.join(","))
            };
            // Pretty print by parsing and re-formatting
            // Simple indentation
            println!("{}", pretty_print_json(&json_str));
        }
        other => print_query_json(other),
    }
}

fn print_query_jsonl(results: &QueryResult) {
    match results {
        QueryResult::Elements(elems) => {
            for elem in elems {
                println!("{}", element_to_json(elem));
            }
        }
        QueryResult::Strings(strs) => {
            for s in strs {
                println!("{}", json_string(s));
            }
        }
        other => print_query_json(other),
    }
}

fn print_query_md(results: &QueryResult) {
    match results {
        QueryResult::Elements(elems) => {
            for elem in elems {
                match elem {
                    Element::Heading { level, text, section, .. } => {
                        let prefix = "#".repeat(*level as usize);
                        println!("{} {}", prefix, text);
                        if !section.content.raw.is_empty() {
                            println!();
                            println!("{}", section.content.raw);
                        }
                        // Print children
                        for child in &section.children {
                            println!();
                            print_section_recursive(child);
                        }
                        println!();
                    }
                    _ => println!("{}", elem.display_text()),
                }
            }
        }
        QueryResult::Strings(strs) => {
            for s in strs {
                println!("{}", s);
            }
        }
        other => print_query_plain(other),
    }
}

fn print_query_tree(results: &QueryResult) {
    match results {
        QueryResult::Elements(elems) => {
            let count = elems.len();
            for (i, elem) in elems.iter().enumerate() {
                let is_last = i == count - 1;
                let connector = if is_last { "└──" } else { "├──" };
                println!("{}{}", connector, elem.display_text());
            }
            if count > 0 {
                println!();
            }
        }
        other => print_query_plain(other),
    }
}

