        headers: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    Blockquote {
        content: String,
    },
}

#[derive(Debug, Clone)]
pub struct ListItem {
    pub content: String,
    pub checked: Option<bool>,
    pub inline: Vec<InlineItem>,
}

#[derive(Debug, Clone)]
pub enum InlineItem {
    Text { value: String },
    Code { value: String },
    Bold { value: String },
    Italic { value: String },
    Link { text: String, url: String, title: Option<String> },
    Image { alt: String, src: String, title: Option<String> },
}

// All extracted elements for querying
#[derive(Debug, Clone)]
pub enum Element {
    Heading {
        level: u8,
        text: String,
        line: usize, // 1-indexed actual line of heading
        section: Section,
    },
    Code {
        language: String,
        content: String,
        start_line: usize,
        end_line: usize,
    },
    Link {
        text: String,
        url: String,
        link_type: String, // "external", "relative", "anchor"
    },
    Image {
        alt: String,
        src: String,
        title: Option<String>,
    },
    Table {
        headers: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    List {
        ordered: bool,
        items: Vec<ListItem>,
    },
    Blockquote {
        content: String,
    },
}

impl Element {
    pub fn type_name(&self) -> &str {
        match self {
            Element::Heading { .. } => "heading",
            Element::Code { .. } => "code",
            Element::Link { .. } => "link",
            Element::Image { .. } => "image",
            Element::Table { .. } => "table",
            Element::List { .. } => "list",
            Element::Blockquote { .. } => "blockquote",
        }
    }

    pub fn display_text(&self) -> String {
        match self {
            Element::Heading { level, text, .. } => {
                format!("{} {}", "#".repeat(*level as usize), text)
            }
            Element::Code { language, content, .. } => {
                format!("```{}\n{}\n```", language, content)
            }
            Element::Link { text, url, .. } => {
                format!("[{}]({})", text, url)
            }
            Element::Image { alt, src, .. } => {
                format!("![{}]({})", alt, src)
            }
            Element::Table { headers, rows } => {
                let header_row = format!("| {} |", headers.join(" | "));
                let sep_row = format!("| {} |", headers.iter().map(|_| "---").collect::<Vec<_>>().join(" | "));
                let data_rows: Vec<String> = rows.iter().map(|r| format!("| {} |", r.join(" | "))).collect();
                let mut result = vec![header_row, sep_row];
                result.extend(data_rows);
                result.join("\n")
            }
            Element::List { ordered, items } => {
                items.iter().enumerate().map(|(i, item)| {
                    let prefix = if *ordered {
                        format!("{}.", i + 1)
                    } else if let Some(checked) = item.checked {
                        if checked { "- [x]".to_string() } else { "- [ ]".to_string() }
                    } else {
                        "-".to_string()
                    };
                    format!("{} {}", prefix, item.content)
                }).collect::<Vec<_>>().join("\n")
            }
            Element::Blockquote { content } => {
                content.lines().map(|l| format!("> {}", l)).collect::<Vec<_>>().join("\n")
            }
        }
    }
}

pub fn slugify(text: &str) -> String {
    let mut result = String::new();
    let mut prev_hyphen = false;

    for ch in text.chars() {
        if ch.is_alphanumeric() {
            result.push(ch.to_ascii_lowercase());
            prev_hyphen = false;
        } else if !result.is_empty() {
            // Any non-alphanumeric char becomes a separator
            if !prev_hyphen {
                result.push('-');
                prev_hyphen = true;
            }
        }
    }

    // Remove trailing hyphen
    while result.ends_with('-') {
        result.pop();
    }

    result
}

fn extract_heading_text(text: &str) -> String {
    // For headings, inline code content is removed (just the backtick content),
    // bold/italic markers are removed (text kept)
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        match chars[i] {
            '`' => {
                // Inline code: remove the content
                i += 1;
                while i < chars.len() && chars[i] != '`' {
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip closing backtick
            }
            '*' | '_' => {
                let marker = chars[i];
                if i + 1 < chars.len() && chars[i + 1] == marker {
                    i += 2; // skip **
                } else {
                    i += 1; // skip *
                }
            }
            c => {
                result.push(c);
                i += 1;
            }
        }
    }

    result
}

fn count_words(text: &str) -> usize {
    text.split_whitespace().count()
}

fn parse_atx_heading(line: &str) -> Option<(u8, String)> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('#') {
        return None;
    }

    let mut level = 0u8;
    let chars: Vec<char> = trimmed.chars().collect();

    while level < chars.len() as u8 && chars[level as usize] == '#' {
        level += 1;
    }

    if level > 6 {
        return None;
    }

    if level as usize >= chars.len() {
        // Just hashes with no space - treat as paragraph, not heading
        return None;
    }

    // Must have a space after the hashes (or end of line for empty heading)
    if chars[level as usize] != ' ' {
        return None;
    }

    let text: String = chars[(level as usize + 1)..].iter().collect();
    // Remove trailing hashes if present (e.g., "## Heading ##" -> "Heading")
    let text = text.trim_end_matches('#').trim_end().to_string();

    Some((level, text))
}

fn is_setext_h1(line: &str) -> bool {
    let trimmed = line.trim();
    !trimmed.is_empty() && trimmed.chars().all(|c| c == '=') && trimmed.len() >= 1
}

fn is_setext_h2(line: &str) -> bool {
    let trimmed = line.trim();
    !trimmed.is_empty() && trimmed.chars().all(|c| c == '-') && trimmed.len() >= 2
}

struct HeadingInfo {
    line_idx: usize,   // 0-indexed line of the heading
    level: u8,
    raw_title: String, // raw title before inline stripping
}

pub fn parse_document(content: &str) -> Document {
    if content.trim().is_empty() {
        // Empty document - shouldn't happen (we check before calling)
        return Document {
            sections: vec![],
            metadata: DocumentMetadata {
                source: None,
                heading_count: 0,
                max_depth: 0,
                word_count: 0,
            },
        };
    }

    let lines: Vec<&str> = content.lines().collect();
    let word_count = count_words(content);

    // Calculate byte offsets for each line
    let mut line_byte_offsets = Vec::with_capacity(lines.len() + 1);
    let mut offset = 0usize;
    line_byte_offsets.push(0);
    for line in &lines {
        offset += line.len() + 1; // +1 for newline
        line_byte_offsets.push(offset);
    }
    // Handle case where content doesn't end with newline
    // The last line offset might be beyond content length

    // First pass: find all headings
    let mut headings: Vec<HeadingInfo> = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];

        if let Some((level, title)) = parse_atx_heading(line) {
            headings.push(HeadingInfo { line_idx: i, level, raw_title: title });
            i += 1;
        } else if i + 1 < lines.len() && !line.trim().is_empty() {
            // Check for setext headings
            let next = lines[i + 1];
            if is_setext_h1(next) {
                headings.push(HeadingInfo { line_idx: i, level: 1, raw_title: line.trim().to_string() });
                i += 2; // skip heading line and underline
            } else if is_setext_h2(next) {
                headings.push(HeadingInfo { line_idx: i, level: 2, raw_title: line.trim().to_string() });
                i += 2;
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    // If no headings, create synthetic "# Input" heading
    if headings.is_empty() {
        let raw_content = content.trim_end().to_string();
        let section = Section {
            id: "input".to_string(),
            level: 1,
            title: "Input".to_string(),
            slug: "input".to_string(),
            position: Position {
                line: 2,
                offset: line_byte_offsets.get(1).copied().unwrap_or(content.len()),
            },
            content: SectionContent {
                raw: raw_content.clone(),
                blocks: parse_blocks(&raw_content),
            },
            children: Vec::new(),
        };

        return Document {
            sections: vec![section],
            metadata: DocumentMetadata {
                source: None,
                heading_count: 1,
                max_depth: 1,
                word_count,
            },
        };
    }

    // Build sections
    // For each heading:
    // - position.line = heading_line_idx + 2 (1-indexed + 1 for content start)
    // - position.offset = byte offset after heading line (end of heading line including \n)
    // - raw content = lines from (heading_line + 1) to (next_heading_line - 1)
    //   where next_heading is the NEXT heading in the flat list (regardless of level)

    let n = headings.len();
    let mut flat_sections: Vec<Section> = Vec::new();

    for idx in 0..n {
        let h = &headings[idx];

        // Calculate position
        let heading_line_idx = h.line_idx;
        let pos_line = heading_line_idx + 2; // 1-indexed, content is on line after heading

        // For setext headings, the heading takes 2 lines
        // The heading line_idx is the text line, and the next line is the underline
        // The content starts after the underline
        let is_setext = if let Some((_, _)) = parse_atx_heading(lines[heading_line_idx]) {
            false
        } else {
            true
        };

        let content_start_line_idx = if is_setext {
            heading_line_idx + 2 // skip text + underline
        } else {
            heading_line_idx + 1
        };

        // Position offset = byte offset of the first byte after the heading line
        // For ATX: after the "# Title\n" line
        // For setext: after the "===\n" line  
        let offset_line = if is_setext {
            heading_line_idx + 1 // the underline
        } else {
            heading_line_idx
        };
        let pos_offset = line_byte_offsets.get(offset_line + 1).copied()
            .unwrap_or(content.len());

        // Content ends at the next heading (any level) or EOF
        let content_end_line_idx = if idx + 1 < n {
            headings[idx + 1].line_idx
        } else {
            lines.len()
        };

        // Extract raw content
        let raw_lines: Vec<&str> = if content_start_line_idx < content_end_line_idx {
            lines[content_start_line_idx..content_end_line_idx].to_vec()
        } else {
            vec![]
        };
        let raw = raw_lines.join("\n").trim_end().to_string();

        // Parse heading title
        let title = extract_heading_text(&h.raw_title);
        let slug = slugify(&title);

        let section = Section {
            id: slug.clone(),
            level: h.level,
            title,
            slug,
            position: Position {
                line: pos_line,
                offset: pos_offset,
            },
            content: SectionContent {
                raw: raw.clone(),
                blocks: parse_blocks(&raw),
            },
            children: Vec::new(),
        };

        flat_sections.push(section);
    }

    // Build tree structure from flat list
    let sections = build_tree(flat_sections);
    let heading_count = count_all_headings(&sections);
    let max_depth = calc_max_depth(&sections, 0);

    Document {
        sections,
        metadata: DocumentMetadata {
            source: None,
            heading_count,
            max_depth,
            word_count,
        },
    }
}

fn build_tree(sections: Vec<Section>) -> Vec<Section> {
    if sections.is_empty() {
        return sections;
    }

    // Use a stack-based approach
    // Stack contains (level, section) pairs
    // When we see a section at level L, pop all stack entries with level >= L,
    // and make the popped entries children of whatever is left on stack

    let mut result: Vec<Section> = Vec::new();
    // Each entry is (parent_level, children_vec)
    // We'll track ancestors as a stack of sections
    let mut stack: Vec<Section> = Vec::new();

    for section in sections {
        // Pop sections that are >= current level (they can't be parents)
        while let Some(top) = stack.last() {
            if top.level >= section.level {
                let child = stack.pop().unwrap();
                if let Some(parent) = stack.last_mut() {
                    parent.children.push(child);
                } else {
                    result.push(child);
                }
            } else {
                break;
            }
        }
        stack.push(section);
    }

    // Drain remaining stack
    while stack.len() > 1 {
        let child = stack.pop().unwrap();
        stack.last_mut().unwrap().children.push(child);
    }

    if let Some(top) = stack.pop() {
        result.push(top);
    }

    result
}

fn count_all_headings(sections: &[Section]) -> usize {
    sections.iter().map(|s| 1 + count_all_headings(&s.children)).sum()
}

fn calc_max_depth(sections: &[Section], current_depth: usize) -> usize {
    if sections.is_empty() {
        return current_depth;
    }
    sections.iter().map(|s| {
        calc_max_depth(&s.children, current_depth + 1)
    }).max().unwrap_or(current_depth)
}

fn is_list_item(line: &str) -> bool {
    let trimmed = line.trim_start();
    if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") {
        return true;
    }
    if trimmed.starts_with("- [") || trimmed.starts_with("* [") {
        return true;
    }
    // Check ordered list: "1. " or "1) "
    let mut chars = trimmed.chars().peekable();
    let mut has_digit = false;
    loop {
        match chars.next() {
            Some(c) if c.is_ascii_digit() => has_digit = true,
            Some('.' ) | Some(')') if has_digit => return chars.next() == Some(' '),
            _ => break,
        }
    }
    false
}

fn parse_list_item(line: &str) -> (String, Option<bool>) {
    let trimmed = line.trim_start();

    // Check for checkbox
    if trimmed.starts_with("- [ ] ") || trimmed.starts_with("* [ ] ") || trimmed.starts_with("+ [ ] ") {
        return (trimmed[6..].to_string(), Some(false));
    }
    if trimmed.starts_with("- [x] ") || trimmed.starts_with("* [x] ") || trimmed.starts_with("+ [x] ")
        || trimmed.starts_with("- [X] ") || trimmed.starts_with("* [X] ") || trimmed.starts_with("+ [X] ") {
        return (trimmed[6..].to_string(), Some(true));
    }

    // Unordered
    if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") {
        return (trimmed[2..].to_string(), None);
    }

    // Ordered: "1. " or "1) "
    if let Some(dot_pos) = trimmed.find(". ") {
        let prefix = &trimmed[..dot_pos];
        if prefix.chars().all(|c| c.is_ascii_digit()) {
            return (trimmed[dot_pos+2..].to_string(), None);
        }
    }
    if let Some(paren_pos) = trimmed.find(") ") {
        let prefix = &trimmed[..paren_pos];
        if prefix.chars().all(|c| c.is_ascii_digit()) {
            return (trimmed[paren_pos+2..].to_string(), None);
        }
    }

    (trimmed.to_string(), None)
}

fn parse_table_row(line: &str) -> Vec<String> {
    let line = line.trim();
    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').map(|cell| cell.trim().to_string()).collect()
}

fn is_table_separator(line: &str) -> bool {
    let line = line.trim();
    if !line.contains('|') { return false; }
    // Strip outer pipes
    let inner = if line.starts_with('|') { &line[1..] } else { line };
    let inner = if inner.ends_with('|') { &inner[..inner.len()-1] } else { inner };
    inner.split('|').all(|cell| {
        let cell = cell.trim();
        !cell.is_empty() && cell.chars().all(|c| c == '-' || c == ':' || c == ' ')
    })
}

pub fn parse_blocks(content: &str) -> Vec<Block> {
    let mut blocks = Vec::new();
    let lines: Vec<&str> = content.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];

        // Skip blank lines
        if line.trim().is_empty() {
            i += 1;
            continue;
        }

        // Code block (fenced)
        let trimmed_start = line.trim_start();
        if trimmed_start.starts_with("```") {
            let fence = trimmed_start;
            let lang = fence[3..].trim().to_string();
            i += 1;
            let mut code_lines = Vec::new();
            while i < lines.len() && !lines[i].trim_start().starts_with("```") {
                code_lines.push(lines[i]);
                i += 1;
            }
            if i < lines.len() { i += 1; } // skip closing ```
            blocks.push(Block::Code {
                language: lang,
                content: code_lines.join("\n"),
                start_line: 1,
                end_line: 1,
            });
            continue;
        }

        // Table: detect by looking at next line for separator
        if line.contains('|') && i + 1 < lines.len() && is_table_separator(lines[i + 1]) {
            let headers = parse_table_row(line);
            i += 2; // skip header + separator
            let mut rows = Vec::new();
            while i < lines.len() && lines[i].contains('|') && !lines[i].trim().is_empty() {
                rows.push(parse_table_row(lines[i]));
                i += 1;
            }
            blocks.push(Block::Table { headers, rows });
            continue;
        }

        // List
        if is_list_item(line) {
            let first_item_trimmed = line.trim_start();
            let ordered = first_item_trimmed.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
            let mut items = Vec::new();

            while i < lines.len() && !lines[i].trim().is_empty() {
                let curr = lines[i];
                if is_list_item(curr) {
                    let (content, checked) = parse_list_item(curr);
                    let inline = parse_inline(&content);
                    items.push(ListItem { content, checked, inline });
                    i += 1;
                } else if curr.starts_with("  ") || curr.starts_with("\t") {
                    // Continuation - append to last item
                    if let Some(last) = items.last_mut() {
                        last.content.push(' ');
                        last.content.push_str(curr.trim());
                    }
                    i += 1;
                } else {
                    break;
                }
            }

            if !items.is_empty() {
                blocks.push(Block::List { ordered, items });
            }
            continue;
        }

        // Blockquote
        if line.trim_start().starts_with('>') {
            let mut bq_lines = Vec::new();
            while i < lines.len() && (lines[i].trim_start().starts_with('>') || 
                  (!lines[i].trim().is_empty() && !lines[i].trim_start().starts_with('#'))) {
                if lines[i].trim_start().starts_with('>') {
                    let bq_line = lines[i].trim_start().trim_start_matches('>');
                    let bq_line = if bq_line.starts_with(' ') { &bq_line[1..] } else { bq_line };
                    bq_lines.push(bq_line.to_string());
                }
                i += 1;
                if i < lines.len() && lines[i].trim().is_empty() { break; }
            }
            // We currently skip blockquotes (don't add to blocks) because original shows empty
            continue;
        }

        // ATX Heading (within content blocks, for JSON output)
        if let Some((level, text)) = parse_atx_heading(line) {
            let anchor = slugify(&text);
            let inline = parse_inline(&text);
            blocks.push(Block::Heading {
                level,
                content: text,
                inline,
                anchor,
            });
            i += 1;
            continue;
        }

        // Setext heading
        if i + 1 < lines.len() {
            let next = lines[i + 1];
            if is_setext_h1(next) {
                let text = line.trim().to_string();
                let anchor = slugify(&text);
                let inline = parse_inline(&text);
                blocks.push(Block::Heading {
                    level: 1,
                    content: text,
                    inline,
                    anchor,
                });
                i += 2;
                continue;
            }
            if is_setext_h2(next) {
                let text = line.trim().to_string();
                let anchor = slugify(&text);
                let inline = parse_inline(&text);
                blocks.push(Block::Heading {
                    level: 2,
                    content: text,
                    inline,
                    anchor,
                });
                i += 2;
                continue;
            }
        }

        // Paragraph - collect until blank line or block start
        let mut para_lines = Vec::new();
        while i < lines.len() && !lines[i].trim().is_empty()
            && !lines[i].trim_start().starts_with("```")
            && !is_list_item(lines[i])
            && !lines[i].trim_start().starts_with('>')
        {
            let l = lines[i];
            // Check if next line is table separator
            if i + 1 < lines.len() && is_table_separator(lines[i + 1]) {
                para_lines.push(l);
                break;
            }
            // Check if next line is setext marker
            if i + 1 < lines.len() {
                let next = lines[i + 1];
                if is_setext_h1(next) || is_setext_h2(next) {
                    para_lines.push(l);
                    break;
                }
            }
            para_lines.push(l);
            i += 1;
        }

        if !para_lines.is_empty() {
            let content = para_lines.join("\n");
            let inline = parse_inline(&content);
            blocks.push(Block::Paragraph { content, inline });
        }
    }

    blocks
}

pub fn parse_inline(text: &str) -> Vec<InlineItem> {
    let mut items = Vec::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    let mut current_text = String::new();

    while i < chars.len() {
        match chars[i] {
            '!' if i + 1 < chars.len() && chars[i+1] == '[' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 2;
                let mut alt = String::new();
                while i < chars.len() && chars[i] != ']' {
                    alt.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    let mut url_buf = String::new();
                    let mut title_buf: Option<String> = None;
                    while i < chars.len() && chars[i] != ')' {
                        if chars[i] == '"' {
                            // Title
                            i += 1;
                            let mut t = String::new();
                            while i < chars.len() && chars[i] != '"' {
                                t.push(chars[i]);
                                i += 1;
                            }
                            if i < chars.len() { i += 1; } // skip closing "
                            title_buf = Some(t);
                        } else {
                            url_buf.push(chars[i]);
                            i += 1;
                        }
                    }
                    if i < chars.len() { i += 1; } // skip )
                    let url = url_buf.trim().to_string();
                    items.push(InlineItem::Image { alt, src: url, title: title_buf });
                } else {
                    items.push(InlineItem::Text { value: format!("![{}]", alt) });
                }
            }
            '[' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 1;
                let mut link_text = String::new();
                while i < chars.len() && chars[i] != ']' {
                    link_text.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; } // skip ]
                if i < chars.len() && chars[i] == '(' {
                    i += 1;
                    let mut url_buf = String::new();
                    let mut title_buf: Option<String> = None;
                    while i < chars.len() && chars[i] != ')' {
                        if chars[i] == '"' {
                            i += 1;
                            let mut t = String::new();
                            while i < chars.len() && chars[i] != '"' {
                                t.push(chars[i]);
                                i += 1;
                            }
                            if i < chars.len() { i += 1; }
                            title_buf = Some(t);
                        } else {
                            url_buf.push(chars[i]);
                            i += 1;
                        }
                    }
                    if i < chars.len() { i += 1; } // skip )
                    let url = url_buf.trim().to_string();
                    items.push(InlineItem::Link { text: link_text, url, title: title_buf });
                } else {
                    items.push(InlineItem::Text { value: format!("[{}]", link_text) });
                }
            }
            '`' => {
                if !current_text.is_empty() {
                    items.push(InlineItem::Text { value: current_text.clone() });
                    current_text.clear();
                }
                i += 1;
                let mut code = String::new();
                while i < chars.len() && chars[i] != '`' {
                    code.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() { i += 1; }
                items.push(InlineItem::Code { value: code });
            }
            '*' | '_' => {
                let marker = chars[i];
                if i + 1 < chars.len() && chars[i+1] == marker {
                    // Bold
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    i += 2;
                    let mut bold = String::new();
                    while i < chars.len() {
                        if i + 1 < chars.len() && chars[i] == marker && chars[i+1] == marker {
                            i += 2;
                            break;
                        }
                        bold.push(chars[i]);
                        i += 1;
                    }
                    items.push(InlineItem::Bold { value: bold });
                } else {
                    // Italic
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    i += 1;
                    let mut italic = String::new();
                    while i < chars.len() && chars[i] != marker {
                        italic.push(chars[i]);
                        i += 1;
                    }
                    if i < chars.len() { i += 1; }
                    items.push(InlineItem::Italic { value: italic });
                }
            }
            c => {
                current_text.push(c);
                i += 1;
            }
        }
    }

    if !current_text.is_empty() {
        items.push(InlineItem::Text { value: current_text });
    }

    items
}

