    while i < lines.len() {
        let line = lines[i];

        if let Some((level, title)) = parse_atx_heading(line) {
            headings.push(HeadingInfo { line_idx: i, level, raw_title: title });
            i += 1;
        } else if i + 1 < lines.len() && !line.trim().is_empty() {
            // Check for setext headings
            let next = lines[i + 1];
            if is_setext_h1(next) {
                headings.push(HeadingInfo { line_idx: i, level: 1, raw_title: line.trim().to_string() });
                i += 2; // skip heading line and underline
            } else if is_setext_h2(next) {
                headings.push(HeadingInfo { line_idx: i, level: 2, raw_title: line.trim().to_string() });
                i += 2;
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }

