    if headings.is_empty() {
        let raw_content = content.trim_end().to_string();
        let section = Section {
            id: "input".to_string(),
            level: 1,
            title: "Input".to_string(),
            slug: "input".to_string(),
            position: Position {
                line: 2,
                offset: line_byte_offsets.get(1).copied().unwrap_or(content.len()),
            },
            content: SectionContent {
                raw: raw_content.clone(),
