# The JSON content is very similar but:
# 1. My code_block start_line/end_line = 1 (incorrect), expected = 29 (section position.line)
# 2. The Configuration inline format - my version doesn't split at ~

# Let me fix the start_line/end_line for code blocks first
# The expected start_line = the section's position.line
# I need to pass the section's position.line to the parse_blocks function
# OR fix the code block line numbers after parsing

# Actually, looking at the expected values:
# Installation code blocks: start_line = end_line = 29 (which is position.line for Installation)
# CLI Mode code blocks: start_line = end_line = 62 (position.line for CLI Mode)
# Query Language code blocks: start_line = end_line = 96

# So each code block within a section gets start_line = end_line = section's position.line
# This is a global line number, not a within-section line number

# The position.line in my implementation = heading_line_idx + 2 (1-indexed)
# I need to pass this to parse_blocks so code blocks get the correct start_line/end_line

# Let me update the Section creation to set the code block line numbers:

# Plan: After creating a section with parse_blocks, update all code blocks' start_line/end_line
# to the section's position.line

cat >> /workspace/src/markdown.rs << 'RUST_EOF'

fn fix_code_block_lines(section: &mut Section) {
    let pos_line = section.position.line;
    for block in &mut section.content.blocks {
        if let Block::Code { start_line, end_line, .. } = block {
            *start_line = pos_line;
            *end_line = pos_line;
        }
    }
    for child in &mut section.children {
        fix_code_block_lines(child);
    }
}

pub fn fix_all_code_block_lines(sections: &mut Vec<Section>) {
    for section in sections {
        fix_code_block_lines(section);
    }
}
RUST_EOF
