with open('/workspace/src/markdown.rs', 'r') as f:
    content = f.read()

# Find the parse_inline function and add ~ handling
# Add case for '~' before the catch-all 'c =>' case

old = '''            c => {
                current_text.push(c);
                i += 1;
            }
        }
    }

    if !current_text.is_empty() {
        items.push(InlineItem::Text { value: current_text });
    }

    items
}'''

new = '''            '~' => {
                // Strikethrough: ~text~ or ~~text~~
                // Check for ~~ first
                let is_double = i + 1 < chars.len() && chars[i + 1] == '~';
                let marker_len = if is_double { 2 } else { 1 };

                // Look for closing ~ or ~~
                let search_start = i + marker_len;
                let closing_pos = if is_double {
                    // Find ~~
                    let mut pos = search_start;
                    let mut found = None;
                    while pos + 1 < chars.len() {
                        if chars[pos] == '~' && chars[pos+1] == '~' {
                            found = Some(pos);
                            break;
                        }
                        pos += 1;
                    }
                    found
                } else {
                    // Find single ~
                    let mut pos = search_start;
                    let mut found = None;
                    while pos < chars.len() {
                        if chars[pos] == '~' && (pos + 1 >= chars.len() || chars[pos + 1] != '~') {
                            found = Some(pos);
                            break;
                        }
                        pos += 1;
                    }
                    found
                };

                if let Some(end_pos) = closing_pos {
                    // Emit strikethrough
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    let strike_content: String = chars[search_start..end_pos].iter().collect();
                    items.push(InlineItem::Strikethrough { value: strike_content });
                    i = end_pos + marker_len; // skip closing marker
                } else {
                    // No closing ~ found
                    // Emit ~ as text, then rest continues
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    items.push(InlineItem::Text { value: "~".to_string() });
                    i += 1; // skip just the ~
                    // Continue collecting text from next char
                    // (rest will be collected as text normally)
                }
            }
            c => {
                current_text.push(c);
                i += 1;
            }
        }
    }

    if !current_text.is_empty() {
        items.push(InlineItem::Text { value: current_text });
    }

    items
}'''

if old in content:
    content = content.replace(old, new)
    print("Replaced successfully")
else:
    print("Pattern not found!")
    # Show what's near the end of parse_inline
    idx = content.find("if !current_text.is_empty()")
    if idx >= 0:
        print("Found at:", idx)
        print(repr(content[idx-200:idx+100]))

