                        current_text.clear();
                    }
                    let strike_content: String = chars[search_start..end_pos].iter().collect();
                    items.push(InlineItem::Strikethrough { value: strike_content });
                    i = end_pos + marker_len; // skip closing marker
                } else {
                    // No closing ~ found
                    // Emit ~ as text, then rest continues
                    if !current_text.is_empty() {
                        items.push(InlineItem::Text { value: current_text.clone() });
                        current_text.clear();
                    }
                    items.push(InlineItem::Text { value: "~".to_string() });
                    i += 1; // skip just the ~
                    // Continue collecting text from next char
                    // (rest will be collected as text normally)
                }
            }
            c => {
                current_text.push(c);
                i += 1;
            }
        }
    }

    if !current_text.is_empty() {
        items.push(InlineItem::Text { value: current_text });
    }

    items
