#[derive(Debug)]
pub enum Subcommand {
    AtLine(usize),
}

#[derive(Debug)]
pub struct Args {
    pub files: Vec<String>,
    pub list: bool,
    pub tree: bool,
    pub filter: Option<String>,
    pub level: Option<u8>,
    pub output: OutputFormat,
    pub section: Option<String>,
    pub count: bool,
    pub setup_completions: bool,
    pub theme: Option<String>,
    pub color_mode: Option<String>,
    pub no_images: bool,
    pub images: bool,
    pub query: Option<String>,
    pub query_output: QueryOutputFormat,
    pub query_help: bool,
    pub version: bool,
    pub help: bool,
    pub subcommand: Option<Subcommand>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum OutputFormat {
    Plain,
    Json,
    Tree,
}

#[derive(Debug, Clone, PartialEq)]
pub enum QueryOutputFormat {
    Plain,
    Json,
    JsonPretty,
    Jsonl,
    Md,
    Tree,
}

pub fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut parsed = Args {
        files: Vec::new(),
        list: false,
        tree: false,
        filter: None,
        level: None,
        output: OutputFormat::Plain,
        section: None,
        count: false,
        setup_completions: false,
        theme: None,
        color_mode: None,
        no_images: false,
        images: false,
        query: None,
        query_output: QueryOutputFormat::Plain,
        query_help: false,
        version: false,
        help: false,
        subcommand: None,
    };

    let mut i = 1; // skip program name

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" => {
                print_short_help();
                std::process::exit(0);
            }
            "--help" => {
                print_long_help();
                std::process::exit(0);
            }
            "-V" | "--version" => {
                parsed.version = true;
                return Ok(parsed);
            }
            "-l" | "--list" => parsed.list = true,
            "--tree" => parsed.tree = true,
            "--count" => parsed.count = true,
            "--setup-completions" => parsed.setup_completions = true,
            "--no-images" => parsed.no_images = true,
            "--images" => parsed.images = true,
            "--query-help" => parsed.query_help = true,
            "--filter" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --filter requires a value".to_string());
                }
                parsed.filter = Some(args[i].clone());
            }
            s if s.starts_with("--filter=") => {
                parsed.filter = Some(s[9..].to_string());
            }
            "-L" | "--level" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --level requires a value".to_string());
                }
                parsed.level = Some(args[i].parse::<u8>().map_err(|_| "error: invalid level value".to_string())?);
            }
            s if s.starts_with("--level=") => {
                parsed.level = Some(s[8..].parse::<u8>().map_err(|_| "error: invalid level value".to_string())?);
            }
            "-o" | "--output" => {
                i += 1;
                if i >= args.len() {
                    return Err("error: --output requires a value".to_string());
                }
                parsed.output = parse_output_format(&args[i])?;
            }
            s if s.starts_with("--output=") => {
                parsed.output = parse_output_format(&s[9..])?;
            }
            "-s" | "--section" => {
                i += 1;
                if i >= args.len() {
